// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address _target, uint256 _balance, uint256 _sendValue) public {
        vm.assume(_target != address(0) && _target != address(c));
        vm.assume(_balance >= _sendValue);
        vm.deal(address(c), _balance);
        uint256 beforeBal = _target.balance;
        vm.prank(c.owner());
        c.sendMoney(_target, _sendValue);
        uint256 afterBal = _target.balance;
        assertTrue(afterBal == beforeBal + _sendValue);
    }
}
